<?php
declare(strict_types=1);
require_once __DIR__ . '/../../helpers/auth.php'; require_once __DIR__ . '/../../models/Attendance.php'; require_once __DIR__ . '/../_json.php'; if (!is_logged_in()) { json_response(['success' => false, 'message' => 'Authentication required.'], 401); } if ($_SERVER['REQUEST_METHOD'] !== 'POST') { json_response(['success' => false, 'message' => 'POST required.'], 405); } $payload = json_decode((string) file_get_contents('php://input'), true); $payload = is_array($payload) ? $payload : $_POST; $memberId = Attendance::memberIdForUser((int) current_user_id()); if (!$memberId) { json_response(['success' => false, 'message' => 'Member profile not found.'], 404); } $session = Attendance::sessionByQr((string) ($payload['token'] ?? '')); if (!$session) { json_response(['success' => false, 'message' => 'QR code is invalid or expired.'], 422); } try { Attendance::record((int) $session['id'], $memberId, 'QR_CODE', null); json_response(['success' => true, 'message' => 'Attendance check-in recorded.']); } catch (DomainException $exception) { json_response(['success' => false, 'message' => $exception->getMessage()], 409); } catch (Throwable $exception) { json_response(['success' => false, 'message' => 'Attendance could not be recorded.'], 500); }
